// Low-resolution translational motion. Border tiles keep a moving subject from
// dominating the camera estimate; the global match is a texture-poor fallback.
function match(a,b,n,x0,x1,y0,y1){let best=Infinity,second=Infinity,bx=0,by=0;for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++){let cost=0,count=0;for(let y=y0;y<y1;y+=2)for(let x=x0;x<x1;x+=2){cost+=Math.min(40,Math.abs(a[y*n+x]-b[(y+dy)*n+x+dx]));count++}cost/=Math.max(1,count);if(cost<best){second=best;best=cost;bx=dx;by=dy}else second=Math.min(second,cost)}return best>28||second-best<.04?null:[bx,by]}
const median=a=>{const s=[...a].sort((x,y)=>x-y),m=s.length>>1;return s.length%2?s[m]:(s[m-1]+s[m])/2};
export function translation(a,b,n=48){const shifts=[];for(const cy of [11,24,37])for(const cx of [11,24,37]){if(cx===24&&cy===24)continue;const r=5,v=match(a,b,n,cx-r,cx+r+1,cy-r,cy+r+1);if(v)shifts.push(v)}const v=shifts.length>=3?[median(shifts.map(s=>s[0])),median(shifts.map(s=>s[1]))]:match(a,b,n,7,n-7,7,n-7);return v?[v[0]/n,v[1]/n]:[0,0]}

// Points are already the accumulated camera path. A local linear fit removes
// jitter while retaining a deliberate constant pan; TRIPOD fits a fixed path.
export function smoothPath(points,strength){const radius={WEAK:2,HANDHELD:2,MEDIUM:5,NATURAL:5,STRONG:10,GIMBAL:10,TRIPOD:18}[strength]||5,tripod=strength==='TRIPOD';let max=0;const result=points.map((p,i)=>{let sw=0,st=0,sx=0,sy=0,stt=0,stx=0,sty=0;for(let j=Math.max(0,i-radius);j<=Math.min(points.length-1,i+radius);j++){const q=points[j],w=radius+1-Math.abs(j-i),t=q.time-p.time;sw+=w;st+=w*t;sx+=w*q.x;sy+=w*q.y;stt+=w*t*t;stx+=w*t*q.x;sty+=w*t*q.y}const den=sw*stt-st*st,fit=(sum,sumt)=>tripod?sum/sw:(den>1e-12?(sum*stt-st*sumt)/den:sum/sw);const x=Math.max(-.08,Math.min(.08,fit(sx,stx)-p.x)),y=Math.max(-.08,Math.min(.08,fit(sy,sty)-p.y));max=Math.max(max,Math.abs(x),Math.abs(y));return{time:p.time,x,y}});const scale=1/Math.max(.82,1-2*max)+.01;return{points:result,scale,crop:1-1/scale}}
export function correctionAt(path,t){const p=path.points;if(!p.length)return{x:0,y:0};let lo=0,hi=p.length-1;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(p[mid].time<=t)lo=mid;else hi=mid-1}const a=p[lo],b=p[Math.min(lo+1,p.length-1)],f=b.time>a.time?Math.max(0,Math.min(1,(t-a.time)/(b.time-a.time))):0;return{x:a.x+(b.x-a.x)*f,y:a.y+(b.y-a.y)*f};}
